import * as crypto from 'crypto';
import { EventEmitter } from 'events';

interface FeatureFlag {
  name: string;
  enabled: boolean;
  rolloutPercentage: number;
  metadata?: Record<string, string>;
}

interface CacheEntry {
  data: Buffer;
  iv: Buffer;
  tag: Buffer;
  timestamp: number;
}

interface NodeConfig {
  nodeId: string;
  host: string;
  port: number;
  region: string;
}

class EncryptionContext {
  private key: Buffer;
  private counterState: Buffer;
  private epoch: number;

  constructor(masterKey: string, nodeId: string) {
    this.key = crypto.scryptSync(masterKey, nodeId, 32);
    this.epoch = 0;
    this.counterState = Buffer.alloc(12);
    this.advanceCounter();
  }

  private advanceCounter(): void {
    const epochBytes = Buffer.alloc(4);
    epochBytes.writeUInt32BE(this.epoch);
    const nodeEntropy = crypto.createHash('sha256')
      .update(this.counterState)
      .update(epochBytes)
      .digest();
    nodeEntropy.copy(this.counterState, 0, 0, 12);
    this.epoch++;
  }

  generateIV(): Buffer {
    const iv = Buffer.from(this.counterState);
    this.advanceCounter();
    return iv;
  }

  getKey(): Buffer {
    return this.key;
  }
}

class DistributedCacheClient extends EventEmitter {
  private nodes: Map<string, NodeConfig> = new Map();
  private encContexts: Map<string, EncryptionContext> = new Map();
  private cache: Map<string, CacheEntry> = new Map();
  private featureFlags: Map<string, FeatureFlag> = new Map();
  private replicationFactor: number;

  constructor(private masterKey: string, replicationFactor = 3) {
    super();
    this.replicationFactor = replicationFactor;
  }

  registerNode(config: NodeConfig): void {
    this.nodes.set(config.nodeId, config);
    this.encContexts.set(
      config.nodeId,
      new EncryptionContext(this.masterKey, config.nodeId)
    );
  }

  setFeatureFlag(flag: FeatureFlag): void {
    this.featureFlags.set(flag.name, flag);
    this.emit('flag-updated', flag);
  }

  private getEncryptionContext(key: string): EncryptionContext {
    const targetNode = this.resolveNode(key);
    const ctx = this.encContexts.get(targetNode);
    if (!ctx) throw new Error(`No encryption context for node ${targetNode}`);
    return ctx;
  }

  private resolveNode(key: string): string {
    const hash = crypto.createHash('md5').update(key).digest();
    const nodeIds = Array.from(this.nodes.keys());
    const index = hash.readUInt32BE(0) % nodeIds.length;
    return nodeIds[index];
  }

  private shouldEncrypt(): boolean {
    const flag = this.featureFlags.get('cache-encryption-v2');
    if (!flag) return true;
    return flag.enabled;
  }

  private usePerKeyIV(): boolean {
    const flag = this.featureFlags.get('per-key-iv-generation');
    if (!flag) return true;
    return flag.enabled;
  }

  encrypt(plaintext: Buffer, cacheKey: string): CacheEntry {
    const ctx = this.getEncryptionContext(cacheKey);
    let iv: Buffer;

    if (this.usePerKeyIV()) {
      iv = ctx.generateIV();
    } else {
      // Legacy mode disabled: always use fresh random IV
      iv = crypto.randomBytes(12);
    }

    if (!this.shouldEncrypt()) {
      return {
        data: plaintext,
        iv: Buffer.alloc(12),
        tag: Buffer.alloc(16),
        timestamp: Date.now()
      };
    }

    const cipher = crypto.createCipheriv('aes-256-gcm', ctx.getKey(), iv);
    const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    const tag = cipher.getAuthTag();

    return { data: encrypted, iv, tag, timestamp: Date.now() };
  }

  decrypt(entry: CacheEntry, cacheKey: string): Buffer {
    if (!this.shouldEncrypt()) {
      return entry.data;
    }

    const ctx = this.getEncryptionContext(cacheKey);
    const decipher = crypto.createDecipheriv('aes-256-gcm', ctx.getKey(), entry.iv);
    decipher.setAuthTag(entry.tag);
    return Buffer.concat([decipher.update(entry.data), decipher.final()]);
  }

  async set(key: string, value: Buffer): Promise<void> {
    const entry = this.encrypt(value, key);
    this.cache.set(key, entry);

    // Replicate to other nodes
    const replicas = this.getReplicaNodes(key);
    for (const replica of replicas) {
      await this.replicateToNode(replica, key, entry);
    }
  }

  async get(key: string): Promise<Buffer | null> {
    const entry = this.cache.get(key);
    if (!entry) return null;
    return this.decrypt(entry, key);
  }

  private getReplicaNodes(key: string): string[] {
    const primary = this.resolveNode(key);
    const allNodes = Array.from(this.nodes.keys());
    const replicas: string[] = [];
    let startIdx = allNodes.indexOf(primary);
    for (let i = 1; i <= this.replicationFactor && i < allNodes.length; i++) {
      replicas.push(allNodes[(startIdx + i) % allNodes.length]);
    }
    return replicas;
  }

  private async replicateToNode(
    nodeId: string,
    key: string,
    entry: CacheEntry
  ): Promise<void> {
    this.emit('replicate', { nodeId, key, entry });
  }

  getStats(): { entries: number; nodes: number; flags: number } {
    return {
      entries: this.cache.size,
      nodes: this.nodes.size,
      flags: this.featureFlags.size
    };
  }
}

export { DistributedCacheClient, FeatureFlag, NodeConfig, EncryptionContext };
